 IF EXISTS(SELECT 1 FROM saas.in_store_operations WHERE sale_id=sale AND (result_payload->'sale'->'customerName'<>'null'::jsonb OR result_payload->'sale'->'note'<>'null'::jsonb)) OR EXISTS(SELECT 1 FROM saas.in_store_payment_attestations WHERE sale_id=sale AND slip_reference IS NOT NULL) OR EXISTS(SELECT 1 FROM saas.in_store_sales s WHERE s.id=sale AND (s.intent->'customerName'<>'null'::jsonb OR s.intent->'note'<>'null'::jsonb)) THEN RAISE EXCEPTION 'deleted POS order retains personal snapshots';END IF;
 IF NOT EXISTS(SELECT 1 FROM saas.in_store_price_snapshots WHERE sale_id=sale AND provenance->>'sourceKind'='base' AND provenance->>'unitPriceCents'='11000' AND provenance->>'variantVersion' IS NOT NULL AND provenance->>'productVersion' IS NOT NULL AND provenance->'trace'->>'method'='fixed_try') THEN RAISE EXCEPTION 'prepare audit provenance missing';END IF;
 RAISE NOTICE 'POS157 behavioral checks passed';
END $test$;
